<script setup>
import { computed } from "vue";
const props = defineProps({ match: Object, confirmed: Boolean }); const emit = defineEmits(["back", "next", "update:confirmed"]);
const allowed = computed(() => props.match.classification === 'Suitable' || (props.match.classification === 'Borderline' && props.confirmed));
</script>
<template><section class="screen"><header class="screen-heading"><div><p class="eyebrow">ETAPA 4 DE 4 · RESULTADO</p><h1>Entenda a aderência antes de gerar.</h1><p>Forças e gaps sempre apontam para evidências confirmadas.</p></div><q-badge outline color="primary">{{ match.classification }}</q-badge></header><div class="score-panel"><div><span>ADERÊNCIA</span><strong>{{ match.score }}<small>/100</small></strong></div><p>{{ match.summary }}</p></div><div class="result-grid"><q-card flat bordered><q-card-section><h2>Pontos fortes</h2><div v-for="item in match.strengths" :key="item.title" class="result-item"><q-icon name="check_circle" color="positive"/><div><strong>{{ item.title }}</strong><p>{{ item.evidence }}</p></div></div></q-card-section></q-card><q-card flat bordered><q-card-section><h2>Gaps</h2><div v-for="item in match.gaps" :key="item.title" class="result-item"><q-icon name="priority_high" color="warning"/><div><strong>{{ item.title }}</strong><p>{{ item.detail }}</p><q-badge outline color="warning">{{ item.level }}</q-badge></div></div></q-card-section></q-card></div><q-card flat bordered class="radar-table"><q-card-section><h2>Competências: perfil × vaga</h2><table><thead><tr><th>Categoria</th><th>Perfil</th><th>Vaga</th></tr></thead><tbody><tr v-for="item in match.radar" :key="item.label"><td>{{ item.label }}</td><td>{{ item.candidate }}</td><td>{{ item.role }}</td></tr></tbody></table></q-card-section></q-card><q-banner v-if="match.classification === 'Not suitable'" class="notice error">A geração foi bloqueada porque a aderência não é suficiente.</q-banner><q-checkbox v-if="match.classification === 'Borderline'" :model-value="confirmed" label="Entendo as ressalvas e quero gerar somente com as evidências confirmadas." @update:model-value="emit('update:confirmed', $event)"/><footer class="screen-actions"><q-btn flat no-caps label="Editar vaga" @click="emit('back')"/><q-btn unelevated no-caps color="primary" :disable="!allowed" label="Gerar candidatura" icon-right="arrow_forward" @click="emit('next')"/></footer></section></template>
